CREATE OR REPLACE FUNCTION public.accept_dancer_agreement(p_version text, p_accepted boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if auth.uid() is null then raise exception 'Sign in required.' using errcode = '42501'; end if;
  perform 1 from public.app_users u where u.id = auth.uid() and u.role = 'dancer' and u.account_state = 'active' for share;
  if not found then raise exception 'An active dancer account is required.' using errcode = '42501'; end if;
  if p_accepted is distinct from true or not exists (
    select 1 from public.dancer_agreement_versions v where v.version = p_version and v.is_current
  ) then raise exception 'Accept the current Dancer Agreement.' using errcode = '22023'; end if;
  insert into public.dancer_agreement_acceptances(user_id, version, acceptance_source)
    values(auth.uid(), p_version, 'dashboard') on conflict (user_id, version) do nothing;
  return public.dancer_agreement_access();
end;
$function$

CREATE OR REPLACE FUNCTION public.audit_admin_media_review()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare n jsonb:=to_jsonb(new); o jsonb:=to_jsonb(old); k text; changed boolean; actor uuid; claim public.admin_review_claims;
begin
  k:=case when TG_TABLE_NAME='image_moderation_records' then 'photo' else 'video' end;
  changed:=n->>'reviewed_by' is not null and (
    n->>'reviewed_at' is distinct from o->>'reviewed_at' or
    (n->>'decision' in ('approved','rejected') and n->>'decision' is distinct from o->>'decision') or
    (k='video' and n->>'status' in ('approved','rejected') and n->>'status' is distinct from o->>'status'));
  actor:=(n->>'reviewed_by')::uuid;
  if changed and exists(select 1 from public.app_users where id=actor and role='admin') then
    perform public.assert_admin_workspace_access(actor,'reviewer');
    select * into claim from public.admin_review_claims where kind=k and item_id=new.id for update;
    if claim.reviewer_id is distinct from actor or claim.expires_at<=now() or claim.version is distinct from old.updated_at then
      raise exception 'Claim the current upload before saving a decision.' using errcode='40001';
    end if;
  end if;
  if n->>'club_reviewed_at' is distinct from o->>'club_reviewed_at' and n->>'club_reviewed_at' is not null then
    insert into public.admin_media_review_events(kind,item_id,stage,decision,actor_id,actor_label,notes,version)
    values(k,new.id,'club','approved',(n->>'club_reviewed_by')::uuid,
      (select coalesce(display_name,email) from public.app_users where id=(n->>'club_reviewed_by')::uuid),n->>'club_review_notes',new.updated_at);
  end if;
  if changed then
    insert into public.admin_media_review_events(kind,item_id,stage,decision,actor_id,actor_label,notes,version)
    values(k,new.id,case when exists(select 1 from public.app_users where id=actor and role='admin') then 'mydancr' else 'club' end,
      coalesce(n->>'review_decision',n->>'status'),actor,
      (select coalesce(display_name,email) from public.app_users where id=actor),n->>'review_notes',new.updated_at);
    delete from public.admin_review_claims where kind=k and item_id=new.id;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.confirm_admission_pass(p_token text, p_arrival_verified boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r public.qr_redemptions; d public.club_deals; v public.venues; actor uuid:=auth.uid();
  stamp timestamptz; local_time timestamp; offer_day date;
begin
  if actor is null then raise exception using errcode='42501',message='Venue staff sign-in is required.';end if;
  select * into r from public.qr_redemptions where redemption_token=p_token and admission_pass_version=1;
  if not found then raise exception using errcode='22023',message='This admission pass is unavailable.';end if;
  perform pg_advisory_xact_lock(hashtext(r.venue_id::text),hashtext(r.session_id));
  if r.customer_id is not null then perform pg_advisory_xact_lock(hashtext(r.venue_id::text),hashtext(r.customer_id::text));end if;
  select * into r from public.qr_redemptions where redemption_token=p_token for update;
  -- Recheck current authorization after waiting for locks. auth.uid() is the
  -- authenticated Supabase identity; no client-supplied staff/venue ID is used.
  select * into v from public.venues where id=r.venue_id and is_active=true
    and page_review_status='published' and published_at is not null;
  if not found or not exists(select 1 from public.app_users where id=actor and role='venue' and account_state='active')
    or not exists(select 1 from public.app_users where id=v.owner_user_id and role='venue' and account_state='active')
    or not (v.owner_user_id=actor or exists(select 1 from public.venue_team_members
      where venue_id=v.id and user_id=actor and status='active' and role in ('manager','staff'))) then
    raise exception using errcode='42501',message='Only authorized staff for this venue can redeem this pass.';
  end if;
  if r.status='redeemed' then
    return jsonb_build_object('status','redeemed','alreadyRedeemed',true,'redeemedAt',r.redeemed_at);
  end if;
  stamp:=clock_timestamp();
  if r.status<>'generated' or r.expires_at<=stamp then
    raise exception using errcode='22023',message='This admission pass has expired or is no longer valid.';
  end if;
  if p_arrival_verified is distinct from true then
    raise exception using errcode='22023',message='Verify the guest arrival method before admitting them.';
  end if;
  select * into d from public.club_deals where id=r.club_deal_id and venue_id=r.venue_id and is_active=true;
  if not found then raise exception using errcode='22023',message='This offer is no longer available.';end if;
  local_time:=stamp at time zone coalesce(nullif(v.timezone,''),'UTC');
  offer_day:=local_time::date;
  if d.valid_start_time is not null and d.valid_end_time is not null and d.valid_start_time>d.valid_end_time then
    if local_time::time>=d.valid_end_time and local_time::time<d.valid_start_time then
      raise exception using errcode='22023',message='This offer is outside its valid admission hours.';
    end if;
    if local_time::time<d.valid_end_time then offer_day:=offer_day-1;end if;
  elsif (d.valid_start_time is not null and local_time::time<d.valid_start_time and d.valid_start_time is distinct from d.valid_end_time)
    or (d.valid_end_time is not null and local_time::time>=d.valid_end_time and d.valid_start_time is distinct from d.valid_end_time) then
    raise exception using errcode='22023',message='This offer is outside its valid admission hours.';
  end if;
  if cardinality(d.valid_days)>0 and not exists(select 1 from unnest(d.valid_days) day
    where lower(left(trim(day),3))=lower(to_char(offer_day,'Dy'))) then
    raise exception using errcode='22023',message='This offer is not valid on this admission date.';
  end if;
  if exists(select 1 from public.qr_redemptions where id<>r.id and venue_id=r.venue_id and status='redeemed'
    and redeemed_at>stamp-interval '24 hours' and (session_id=r.session_id or customer_id=r.customer_id)) then
    raise exception using errcode='23505',message='Admission has already been redeemed at this venue in the last 24 hours.';
  end if;
  update public.qr_redemptions set status='redeemed',redeemed_at=stamp,confirmed_at=stamp,
    first_scanned_at=coalesce(first_scanned_at,stamp),redeemed_by_user_id=actor,arrival_verified_at=stamp where id=r.id;
  insert into public.qr_redemption_events(qr_redemption_id,event_type,actor_user_id,audit)
    values(r.id,'venue_confirmed',actor,jsonb_build_object('method','staff_qr_scan','arrival_method',r.arrival_method,'admission_policy','staff-verified-v1'));
  return jsonb_build_object('status','redeemed','alreadyRedeemed',false,'redeemedAt',stamp);
end $function$

CREATE OR REPLACE FUNCTION public.dancer_agreement_access()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  current_version text;
  accepted_time timestamptz;
  required boolean;
begin
  if auth.uid() is null then raise exception 'Sign in required.' using errcode = '42501'; end if;
  select v.version into strict current_version from public.dancer_agreement_versions v where v.is_current;
  select a.accepted_at into accepted_time from public.dancer_agreement_acceptances a
    where a.user_id = auth.uid() and a.version = current_version;
  select exists(select 1 from public.app_users u where u.id = auth.uid() and u.role = 'dancer' and u.account_state = 'active') into required;
  return jsonb_build_object('required', required, 'accepted', accepted_time is not null,
    'version', current_version, 'acceptedAt', accepted_time);
end;
$function$

CREATE OR REPLACE FUNCTION public.valid_venue_weekly_hours(hours jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare day jsonb;
begin
  if hours is null then return true; end if;
  if jsonb_typeof(hours) <> 'array' then return false; end if;
  if jsonb_array_length(hours) <> 7 then return false; end if;
  for day in select value from jsonb_array_elements(hours) loop
    if jsonb_typeof(day) <> 'object' then return false; end if;
    if day->>'mode' in ('closed', '24-hours') then
      if day - 'mode' <> '{}'::jsonb then return false; end if;
    elsif day->>'mode' = 'custom' then
      if jsonb_typeof(day->'opensAt') is distinct from 'string'
        or jsonb_typeof(day->'closesAt') is distinct from 'string'
        or (day->>'opensAt') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
        or (day->>'closesAt') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
        or day->>'opensAt' = day->>'closesAt'
        or day - array['mode', 'opensAt', 'closesAt'] <> '{}'::jsonb then return false; end if;
    else return false;
    end if;
  end loop;
  return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.void_generated_deal_redemption(p_redemption_id uuid, p_reason text DEFAULT 'admin_marked_suspicious'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
  v_now timestamptz := clock_timestamp();
  v_user_id uuid := auth.uid();
  v_redemption public.qr_redemptions%rowtype;
begin
  if v_user_id is null or not public.is_admin() then
    raise exception using errcode = '42501', message = 'Admin access required.';
  end if;

  if length(trim(coalesce(p_reason, ''))) < 3
    or length(trim(p_reason)) > 180 then
    raise exception using errcode = '22023', message = 'A valid void reason is required.';
  end if;

  select redemption.*
    into v_redemption
  from public.qr_redemptions redemption
  where redemption.id = p_redemption_id
  for update;

  if not found then
    raise exception using errcode = 'P0002', message = 'Redemption not found.';
  end if;

  if v_redemption.status <> 'generated' then
    raise exception using
      errcode = '22023',
      message = 'Only an unused generated QR can be voided. Financial reversals require a separate refund record.';
  end if;

  update public.qr_redemptions
  set
    status = 'voided',
    suspicious = true,
    voided_at = v_now,
    voided_by_admin = v_user_id,
    audit = coalesce(audit, '{}'::jsonb) || jsonb_build_object(
      'voided_by_admin', v_user_id,
      'void_reason', trim(p_reason)
    )
  where id = v_redemption.id;

  insert into public.qr_redemption_events (
    qr_redemption_id,
    event_type,
    actor_user_id,
    audit
  )
  values (
    v_redemption.id,
    'voided',
    v_user_id,
    jsonb_build_object('reason', trim(p_reason))
  );

  return jsonb_build_object(
    'id', v_redemption.id,
    'status', 'voided',
    'suspicious', true
  );
end;
$function$
